"""Generate the single-file throwaway evidence viewer and illustrative state model."""
from pathlib import Path
import json
p=Path(__file__).resolve().parent
report=(p/'evidence/report.json').read_text().replace('</','<\\/')
html='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Portable package lab</title>
<style>body{font:16px/1.55 system-ui,sans-serif;background:#f7f8fa;color:#182333;max-width:1120px;margin:42px auto;padding:0 24px}h1{font-size:36px;letter-spacing:-1px}h2{font-size:21px}button,select{font:inherit;padding:9px 13px;margin:4px;border:1px solid #b8c7ce;border-radius:6px;background:white;color:#183748;cursor:pointer}button:hover{background:#e6f4f2}section{background:white;padding:22px;border-radius:12px;margin:22px 0;border:1px solid #dde5e9}.tag{color:#006b60;font-weight:650}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.cards div{padding:16px;background:#f0f6f5;border-radius:8px}pre{font-size:12px;overflow:auto;max-height:460px;background:#142632;color:#e9f2f5;padding:18px;border-radius:6px;white-space:pre-wrap;word-break:break-word}.muted{color:#526774}select{max-width:100%}output{display:block;padding:14px;background:#eef6f4;margin:12px 0}details{margin:12px 0}</style>
<p class="tag">Agents Assemble · Decision #17 · Throwaway lab</p><h1>What does an imported package prove?</h1><p>Explore how exact content, publisher evidence and local execution permission stay separate when packages move between disconnected installations.</p><p class="muted">The evidence below comes from actual byte parsing and local SQLite fault probes. The free-play controls are an illustrative in-memory model, not the production importer.</p>
<section><h2>Try the import decisions</h2><div class="cards"><div>Package content<br><strong id="content"></strong></div><div>Publisher evidence<br><strong id="trust"></strong></div><div>Execution permission<br><strong id="grant"></strong></div></div>
<div id="actions"></div><output id="message"></output><details open><summary>Complete model state and transitions</summary><pre id="state"></pre></details></section>
<section><h2>Walk through retained evidence</h2><p>Choose a path, then inspect every recorded state. Rejection cases retain their reason; durable round trips and crashes include complete Catalog snapshots.</p><div id="walks"></div><select id="cases" aria-label="Recorded experiment"></select><button id="next">Next observation</button><output id="summary"></output><details open><summary>Complete retained evidence for this observation</summary><pre id="evidence"></pre></details></section>
<section><h2>What remains unproved</h2><p>Full playbook semantic validation, durable source-origin allocation, current upstream revocation, actual component permissions, production storage and moderation/admission integration remain outside this fixture. Import never supplies a runtime binding or a grant.</p><details><summary>Full report, limits and runtime</summary><pre id="report"></pre></details></section>
<script>const report=__REPORT__;
const initial=()=>({content:null,evidence:[],localTrust:true,executionGrant:false,history:[]});let state=initial();
function reduce(s,a){s=structuredClone(s);let result='';switch(a){case'Reset':return initial();case'Import unsigned':if(!s.content)s.content='origin A · version 1 · digest A';result='Exact bytes retained. No publisher proof supplied.';break;case'Import signed':if(!s.content)s.content='origin A · version 1 · digest A';if(!s.evidence.includes('pinned issuer proof'))s.evidence.push('pinned issuer proof');result='Proof retained separately; local trust is checked now.';break;case'Change same version':result=s.content?'Rejected: the same origin/version cannot name different content.':'No existing version yet. Import the original first.';break;case'Crash before commit':result='No partial import becomes visible. Previously committed content is preserved.';break;case'Remove local key':s.localTrust=false;result='Content remains; publisher attribution is now unverified.';break;case'Restore local key':s.localTrust=true;result='Retained evidence can be checked against the restored local key.';break;case'Execute':result='Blocked: import supplies no local runtime binding or execution grant.';break;}s.history.push({action:a,result});return s;}
function render(){document.querySelector('#content').textContent=state.content||'No imported version';document.querySelector('#trust').textContent=state.localTrust&&state.evidence.length?'Verified against local key':'Unverified';document.querySelector('#grant').textContent='Not granted';document.querySelector('#message').textContent=state.history.at(-1)?.result||'Start with an unsigned or signed import.';document.querySelector('#state').textContent=JSON.stringify(state,null,2);}
for(const a of ['Import unsigned','Import signed','Change same version','Crash before commit','Remove local key','Restore local key','Execute','Reset']){const b=document.createElement('button');b.textContent=a;b.onclick=()=>{state=reduce(state,a);render()};document.querySelector('#actions').append(b)}render();
const sel=document.querySelector('#cases');for(let i=0;i<report.scenarios.length;i++){const o=document.createElement('option');o.value=i;o.textContent=(i+1)+'. '+report.scenarios[i].name;sel.append(o)}
function show(){const r=report.scenarios[+sel.value];document.querySelector('#summary').textContent=r.name+' — '+r.outcome;document.querySelector('#evidence').textContent=JSON.stringify(r,null,2)}sel.onchange=show;document.querySelector('#next').onclick=()=>{sel.selectedIndex=(sel.selectedIndex+1)%sel.options.length;show()};
for(const [label,needle] of [['Offline transfer','two isolated'],['Interrupted import','process crash after-blobs'],['Publisher evidence','unsigned upgrade'],['Public redaction','public export remaps']]){const b=document.createElement('button');b.textContent=label;b.onclick=()=>{sel.selectedIndex=report.scenarios.findIndex(x=>x.name.includes(needle));show()};document.querySelector('#walks').append(b)}show();document.querySelector('#report').textContent=JSON.stringify(report,null,2);</script>'''
(p/'lab.html').write_text(html.replace('__REPORT__',report))
print(p/'lab.html')
